import { defineCollection } from 'astro:content';
import { file } from 'astro/loaders';
import { z } from 'astro/zod';

// Generated by scripts/extract.mjs. Any record that breaks this schema fails the build.

export const CATEGORY_SLUGS = [
  'drawing',
  'painting',
  'design',
  'printmaking',
  'ceramics',
  'sculpture',
  'photography',
  'exhibitions',
  'student-projects',
  'faculty',
  'student-spotlight',
] as const;

const legacyPath = z.string().regex(/^legacy\//, 'must point inside legacy/');
const year = z.number().int().min(1990).max(2100).nullable();

const artworks = defineCollection({
  loader: file('src/data/artworks.json'),
  schema: ({ image }) =>
    z
      .object({
        id: z.string().regex(/^[a-z0-9]+(-[a-z0-9]+)*$/, 'id must be a lowercase slug'),
        title: z.string().min(1).nullable(),
        artist: z.string().min(1).nullable(),
        year,
        semester: z.enum(['Spring', 'Fall']).nullable(),
        category: z.enum(CATEGORY_SLUGS),
        medium: z.string().min(1).nullable(),
        dimensions: z.string().min(1).nullable(),
        description: z.string().min(1).nullable(),
        campus: z.enum(['Yuma', 'San Luis']).nullable(),
        course: z.string().min(1).nullable(),
        image: image(),
        width: z.number().int().positive(),
        height: z.number().int().positive(),
        sourcePage: legacyPath.nullable(),
        otherSourcePages: z.array(legacyPath),
        legacyImage: legacyPath,
      })
      .strict(),
});

const laTrips = defineCollection({
  loader: file('src/data/la-trips.json'),
  schema: ({ image }) =>
    z
      .object({
        id: z.string().regex(/^[a-z0-9]+(-[a-z0-9]+)*$/),
        year,
        caption: z.string().min(1).nullable(),
        image: image(),
        sourcePage: legacyPath,
        legacyImage: legacyPath,
      })
      .strict(),
});

export const collections = { artworks, laTrips };
